SELECT *, CORR(quantity, unit_price) OVER (PARTITION BY order_id) AS corr_quantity_unit_price, CUME_DIST() OVER w_recent AS quantity_cume_dist, NTILE(3) OVER (PARTITION BY order_id ORDER BY quantity ASC, id ASC) AS quantity_bucket, SUM(quantity) OVER (PARTITION BY product_id ORDER BY unit_price ASC, id ASC ROWS BETWEEN UNBOUNDED PRECEDING AND CURRENT ROW) AS cumulative_quantity, LEAD(quantity, 1) OVER (PARTITION BY product_id ORDER BY unit_price ASC, id ASC) AS next_quantity FROM order_items WINDOW w_recent AS (PARTITION BY product_id ORDER BY quantity ASC NULLS LAST)
